// Named, pure, chainable value transforms: a port of src/formcast/transforms.py.
//
// Python is the reference. tests/web/fixtures/transforms.json is generated by running the Python
// library (demo/tools/export_conformance.py) and transforms.test.js holds this file to it, error
// messages included. Where JavaScript and Python differ the code below spells Python's rule out
// (see pycompat.js).
//
// A chain step is `{op, args}`. applyChain receives one value per source path. A transform registered
// with takesList (join) consumes that list; any other transform applies to the only value, or is
// mapped over the values when there are several. A source value that is itself a list (a
// multi-select) is one value, not something to map over.

import {
  PY_SPACE_CLASS,
  codePoints,
  compareCodePoints,
  decimalDigitValue,
  hasKey,
  isDict,
  pyEquals,
  pyFloatRepr,
  pyRepr,
  pyStr,
  pyStrip,
  pyTruthy,
  pyTypeName,
} from "./pycompat.js";

/** Raised for every failure Python reports as a FormcastError; `message` is Python's text. */
export class TransformError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.name = "TransformError";
  }
}

/** Stand-in for a Python exception that is not a FormcastError (wrapped by `call`, as Python does). */
class PyError extends Error {}

// ------------------------------------------------------------ args validation
// The arg schemas use only these JSON Schema keywords: type, properties, required,
// additionalProperties, minLength, minimum, maximum, enum (and default, which validation ignores).
// Messages are the ones the jsonschema library produces for them.

function isType(instance, type) {
  switch (type) {
    case "object": return isDict(instance);
    case "array": return Array.isArray(instance);
    case "string": return typeof instance === "string";
    case "integer": return typeof instance === "number" && Number.isInteger(instance);
    case "number": return typeof instance === "number";
    case "boolean": return typeof instance === "boolean";
    case "null": return instance === null;
    default: return false;
  }
}

/** @returns {{path: string[], message: string}[]} */
function schemaErrors(schema, instance, path) {
  const errors = [];
  for (const [keyword, value] of Object.entries(schema)) {
    switch (keyword) {
      case "type": {
        const types = Array.isArray(value) ? value : [value];
        if (!types.some((t) => isType(instance, t))) {
          errors.push({ path, message: `${pyRepr(instance)} is not of type ${types.map(pyRepr).join(", ")}` });
        }
        break;
      }
      case "properties":
        if (isDict(instance)) {
          for (const [name, sub] of Object.entries(value)) {
            if (hasKey(instance, name)) errors.push(...schemaErrors(sub, instance[name], [...path, name]));
          }
        }
        break;
      case "required":
        if (isDict(instance)) {
          for (const name of value) {
            if (!hasKey(instance, name)) errors.push({ path, message: `${pyRepr(name)} is a required property` });
          }
        }
        break;
      case "additionalProperties":
        if (isDict(instance) && value === false) {
          const known = schema.properties ?? {};
          const extras = Object.keys(instance).filter((k) => !hasKey(known, k)).sort(compareCodePoints);
          if (extras.length) {
            const verb = extras.length === 1 ? "was" : "were";
            errors.push({
              path,
              message: `Additional properties are not allowed (${extras.map(pyRepr).join(", ")} ${verb} unexpected)`,
            });
          }
        }
        break;
      case "minLength":
        if (typeof instance === "string" && codePoints(instance).length < value) {
          errors.push({ path, message: `${pyRepr(instance)} ${value === 1 ? "should be non-empty" : "is too short"}` });
        }
        break;
      case "minimum":
        if (typeof instance === "number" && instance < value) {
          errors.push({ path, message: `${pyRepr(instance)} is less than the minimum of ${pyRepr(value)}` });
        }
        break;
      case "maximum":
        if (typeof instance === "number" && instance > value) {
          errors.push({ path, message: `${pyRepr(instance)} is greater than the maximum of ${pyRepr(value)}` });
        }
        break;
      case "enum":
        // the only enum here lists strings, so strict equality is what jsonschema's check amounts to
        if (!value.some((each) => each === instance)) {
          errors.push({ path, message: `${pyRepr(instance)} is not one of ${pyRepr(value)}` });
        }
        break;
      default:
        break; // default and other annotations
    }
  }
  return errors;
}

function comparePaths(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const d = compareCodePoints(a[i], b[i]);
    if (d !== 0) return d;
  }
  return a.length - b.length;
}

// ------------------------------------------------------------------ text helpers

/**
 * Render a scalar as text the way Python's str() does; lists and objects are an error
 * (they need a transform first).
 * @param {unknown} value
 * @returns {string}
 */
export function toText(value) {
  if (typeof value === "string") return value;
  if (Array.isArray(value) || isDict(value)) {
    throw new TransformError(`expected text but got ${pyTypeName(value)}: ${pyRepr(value)}`);
  }
  return pyStr(value);
}

const FALSE_WORDS = new Set(["", "false", "no", "n", "0", "off"]);

/**
 * True to tick a checkbox for a truthy value; false, no, 0, empty and missing leave it unticked.
 * @param {unknown} value
 * @returns {boolean}
 */
export function boolToCheck(value) {
  if (typeof value === "string") return !FALSE_WORDS.has(pyStrip(value).toLowerCase());
  return pyTruthy(value);
}

// ------------------------------------------------------------------------ dates

const ISO_DATE = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

function isLeap(y) {
  return y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0);
}

function daysInMonth(y, m) {
  return [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}

/** @returns {{year: number, month: number, day: number}} */
function toDate(value) {
  const m = typeof value === "string" ? ISO_DATE.exec(value) : null;
  if (m) {
    const [year, month, day] = [Number(m[1]), Number(m[2]), Number(m[3])];
    if (year >= 1 && month >= 1 && month <= 12 && day >= 1 && day <= daysInMonth(year, month)) {
      return { year, month, day };
    }
  }
  throw new TransformError(`invalid date ${pyRepr(value)}: expected an ISO 'YYYY-MM-DD' string or datetime.date`);
}

function dayOfYear({ year, month, day }) {
  let n = day;
  for (let m = 1; m < month; m++) n += daysInMonth(year, m);
  return n;
}

function weekday({ year, month, day }) {
  const d = new Date(0);
  d.setUTCFullYear(year, month - 1, day);
  return d.getUTCDay(); // 0 = Sunday
}

function isoWeek(date) {
  const wd = (weekday(date) + 6) % 7; // 0 = Monday
  const yday = dayOfYear(date) - 1;
  let week = Math.floor((yday - wd + 10) / 7);
  let year = date.year;
  if (week < 1) {
    year -= 1;
    week = isoWeek({ year, month: 12, day: 31 }).week;
  } else if (week === 53 && yday - wd + 3 >= (isLeap(year) ? 366 : 365)) {
    week = 1; // the week's Thursday falls in the next year
    year += 1;
  }
  return { week, year };
}

const pad = (n, width, fill = "0") => String(n).padStart(width, fill);

const COMPOSITE = {
  F: "%Y-%m-%d",
  D: "%m/%d/%y",
  x: "%m/%d/%y",
  T: "%H:%M:%S",
  X: "%H:%M:%S",
  R: "%H:%M",
  r: "%I:%M:%S %p",
  c: "%a %b %e %H:%M:%S %Y",
};

// directives the "-" flag (no padding) applies to
const UNPADDED = new Set(["d", "m", "H", "I", "M", "S", "y", "j", "e", "k", "l", "U", "W", "V", "C", "g"]);

/**
 * Python's date.strftime for a date, so every time field is midnight. Supported: %Y %y %C %m %d %e
 * %B %b %h %A %a %j %H %I %k %l %M %S %f %p %w %u %U %W %V %G %g %F %D %T %R %r %x %X %c %Z %z %n %t
 * %%, and the "-" flag (no padding) on the numeric ones. Python hands the format to the C library,
 * which treats an unknown directive in its own way (glibc keeps it, macOS drops the "%"); here it is
 * kept as written.
 * @param {{year: number, month: number, day: number}} date
 * @param {string} format
 * @returns {string}
 */
function strftime(date, format) {
  const { year, month, day } = date;
  const wd = weekday(date);
  const yday = dayOfYear(date);
  const simple = {
    Y: () => pad(year, 4),
    y: () => pad(year % 100, 2),
    C: () => pad(Math.floor(year / 100), 2),
    m: () => pad(month, 2),
    d: () => pad(day, 2),
    e: () => pad(day, 2, " "),
    B: () => MONTH_NAMES[month - 1],
    b: () => MONTH_NAMES[month - 1].slice(0, 3),
    h: () => MONTH_NAMES[month - 1].slice(0, 3),
    A: () => DAY_NAMES[wd],
    a: () => DAY_NAMES[wd].slice(0, 3),
    j: () => pad(yday, 3),
    H: () => "00",
    I: () => "12",
    k: () => " 0",
    l: () => "12",
    M: () => "00",
    S: () => "00",
    f: () => "000000",
    p: () => "AM",
    w: () => String(wd),
    u: () => String(wd === 0 ? 7 : wd),
    U: () => pad(Math.floor((yday - 1 + 7 - wd) / 7), 2),
    W: () => pad(Math.floor((yday - 1 + 7 - ((wd + 6) % 7)) / 7), 2),
    V: () => pad(isoWeek(date).week, 2),
    G: () => pad(isoWeek(date).year, 4),
    g: () => pad(isoWeek(date).year % 100, 2),
    Z: () => "",
    z: () => "",
    n: () => "\n",
    t: () => "\t",
    "%": () => "%",
  };
  const cps = codePoints(format);
  let out = "";
  for (let i = 0; i < cps.length; i++) {
    if (cps[i] !== "%" || i + 1 >= cps.length) {
      out += cps[i];
      continue;
    }
    const flagged = cps[i + 1] === "-" && i + 2 < cps.length && UNPADDED.has(cps[i + 2]);
    const key = flagged ? cps[i + 2] : cps[i + 1];
    i += flagged ? 2 : 1;
    if (hasKey(COMPOSITE, key)) out += strftime(date, COMPOSITE[key]);
    else if (hasKey(simple, key)) {
      const text = simple[key]();
      out += flagged ? text.replace(/^[0 ]+(?=.)/, "") : text;
    } else out += `%${key}`;
  }
  return out;
}

// ---------------------------------------------------------------------- numbers
// Python formats with Decimal. This is the same arithmetic on an arbitrary-precision coefficient
// (a BigInt) and a power-of-ten exponent.

const NUMBER_TEXT = /^[+-]?(?:\p{Nd}+(?:\.\p{Nd}*)?|\.\p{Nd}+)$/u;

function asciiDigits(s) {
  return codePoints(s).map((ch) => {
    const v = decimalDigitValue(ch);
    return v >= 0 ? String(v) : ch;
  }).join("");
}

/** Parse decimal text such as "-12.50" or "1.5e+22" into {negative, coefficient, exponent}. */
function parseDecimal(text) {
  const m = /^([+-]?)([0-9]*)(?:\.([0-9]*))?(?:e([+-]?[0-9]+))?$/.exec(text);
  const frac = m[3] ?? "";
  return {
    negative: m[1] === "-",
    coefficient: BigInt(`${m[2]}${frac}` || "0"),
    exponent: Number(m[4] ?? 0) - frac.length,
  };
}

function toDecimal(value) {
  if (typeof value === "number" && Number.isFinite(value)) {
    // Python builds Decimal(value) for an int and Decimal(repr(value)) for a float
    return parseDecimal(Number.isInteger(value) && Math.abs(value) < 1e16 ? String(value) : pyFloatRepr(value));
  }
  if (typeof value === "string") {
    const stripped = pyStrip(value);
    if (NUMBER_TEXT.test(stripped)) return parseDecimal(asciiDigits(stripped));
  }
  throw new TransformError(`invalid number ${pyRepr(value)}`);
}

const DEFAULT_PRECISION = 28;
const digitCount = (n) => (n === 0n ? 1 : n.toString().length);

function numberFormat(value, { decimals = 2, thousands = ",", prefix = "" }) {
  const d = toDecimal(value);
  // Python raises InvalidOperation when the rounded coefficient needs more digits than the
  // context precision, which is max(28, digits of the input + decimals + 10)
  const precision = Math.max(DEFAULT_PRECISION, digitCount(d.coefficient) + decimals + 10);
  let coefficient;
  if (d.exponent >= -decimals) {
    coefficient = d.coefficient * 10n ** BigInt(d.exponent + decimals);
  } else {
    const divisor = 10n ** BigInt(-decimals - d.exponent);
    coefficient = d.coefficient / divisor;
    if ((d.coefficient % divisor) * 2n >= divisor) coefficient += 1n; // half up, away from zero
  }
  if (digitCount(coefficient) > precision) throw new TransformError(`cannot format number ${pyRepr(value)}`);
  const isNonzero = coefficient !== 0n;
  // Python then takes abs(q) outside the widened context, which rounds the magnitude to the
  // default 28 significant digits (half even) before it is printed
  let exponent = -decimals;
  if (digitCount(coefficient) > DEFAULT_PRECISION) {
    const divisor = 10n ** BigInt(digitCount(coefficient) - DEFAULT_PRECISION);
    let rounded = coefficient / divisor;
    const rest = coefficient % divisor;
    if (rest * 2n > divisor || (rest * 2n === divisor && rounded % 2n === 1n)) rounded += 1n;
    exponent += digitCount(coefficient) - DEFAULT_PRECISION;
    coefficient = rounded;
    if (digitCount(coefficient) > DEFAULT_PRECISION) {
      coefficient /= 10n;
      exponent += 1;
    }
  }
  let whole;
  let frac = "";
  if (exponent >= 0) whole = (coefficient * 10n ** BigInt(exponent)).toString();
  else {
    const digits = coefficient.toString().padStart(-exponent + 1, "0");
    whole = BigInt(digits.slice(0, digits.length + exponent)).toString();
    frac = digits.slice(digits.length + exponent);
  }
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",").replaceAll(",", () => thousands);
  return (d.negative && isNonzero ? "-" : "") + prefix + grouped + (frac ? `.${frac}` : "");
}

// --------------------------------------------------------------------- registry

const obj = (properties, required = []) => ({ type: "object", properties, required, additionalProperties: false });
const INT = { type: "integer" };
const STR = { type: "string" };

const isBlank = (v) => v === null || v === undefined || v === "";
const nullsafe = (fn) => (value, args) => (value === null || value === undefined ? null : fn(value, args));
const blanksafe = (fn) => (value, args) => (isBlank(value) ? value : fn(value, args));
const decorate = (value, text, before) => {
  if (isBlank(value)) return value; // blank stays blank so decorations don't print on empty fields
  return before ? text + toText(value) : toText(value) + text;
};

const TITLE_PART = new RegExp(`[^${PY_SPACE_CLASS}\\-]+`, "gu");

const BUILTINS = [
  {
    name: "split",
    fn: nullsafe((value, { sep, index }) => {
      const parts = toText(value).split(sep);
      return index >= -parts.length && index < parts.length ? parts.at(index) : "";
    }),
    schema: obj({ sep: { type: "string", minLength: 1 }, index: INT }, ["sep", "index"]),
    doc: 'Split text on `sep` and take part number `index` (0-based, negative allowed; "" if absent).',
  },
  {
    name: "join",
    fn: (values, { sep }) => {
      const parts = values.filter((v) => v !== null && v !== "").map(toText);
      return parts.length ? parts.join(sep) : null;
    },
    schema: obj({ sep: STR }, ["sep"]),
    doc: "Join all source values with `sep`, skipping missing and empty ones (None if all are).",
    takesList: true,
  },
  {
    name: "slice",
    fn: nullsafe((value, { start = 0, end }) => {
      if (Array.isArray(value)) return value.slice(start, end);
      return codePoints(toText(value)).slice(start, end).join("");
    }),
    schema: obj({ start: { ...INT, default: 0 }, end: INT }),
    doc: "Take characters (or list items) from `start` up to but not including `end`.",
  },
  {
    name: "char_at",
    fn: nullsafe((value, { index }) => {
      const chars = codePoints(toText(value));
      return index >= -chars.length && index < chars.length ? chars.at(index) : "";
    }),
    schema: obj({ index: INT }, ["index"]),
    doc: 'Take the single character at `index` (0-based, negative allowed; "" if out of range).',
  },
  { name: "upper", fn: nullsafe((value) => toText(value).toUpperCase()), schema: obj({}), doc: "Convert text to UPPER CASE." },
  { name: "lower", fn: nullsafe((value) => toText(value).toLowerCase()), schema: obj({}), doc: "Convert text to lower case." },
  {
    name: "title",
    fn: nullsafe((value) => toText(value).replace(TITLE_PART, (part) => {
      const [first, ...rest] = codePoints(part);
      return first.toUpperCase() + rest.join("").toLowerCase();
    })),
    schema: obj({}),
    doc: "Convert text to Title Case (each word and hyphenated part capitalized).",
  },
  { name: "strip", fn: nullsafe((value) => pyStrip(toText(value))), schema: obj({}), doc: "Remove leading and trailing whitespace." },
  {
    name: "date_format",
    fn: blanksafe((value, { format }) => strftime(toDate(value), format)),
    schema: obj({ format: { type: "string", minLength: 1 } }, ["format"]),
    doc: 'Format an ISO date (YYYY-MM-DD) with a strftime pattern, e.g. "%m/%d/%Y".',
  },
  {
    name: "date_part",
    fn: blanksafe((value, { part, pad: width = 0 }) => {
      const d = toDate(value);
      const number = { month: d.month, day: d.day, year: d.year, year2: d.year % 100 }[part];
      return String(number).padStart(Math.max(width, part === "year2" ? 2 : 0), "0");
    }),
    schema: obj({ part: { enum: ["month", "day", "year", "year2"] }, pad: { type: "integer", minimum: 0, default: 0 } }, ["part"]),
    doc: "Take month, day, year (4 digits) or year2 (2 digits) of an ISO date, zero-padded to `pad`.",
  },
  {
    name: "number_format",
    fn: blanksafe(numberFormat),
    schema: obj({
      decimals: { type: "integer", minimum: 0, maximum: 12, default: 2 },
      thousands: { type: "string", default: "," },
      prefix: { type: "string", default: "" },
    }),
    doc: "Format a number with fixed `decimals` (rounded half up), a thousands separator and a prefix.",
  },
  {
    name: "bool_to_check",
    fn: (value) => boolToCheck(value),
    schema: obj({}),
    doc: "True to tick a checkbox for a truthy value; false, no, 0, empty and missing leave it unticked.",
  },
  {
    name: "equals",
    fn: (item, { value }) => (item === null ? false : pyEquals(item, value)),
    schema: obj({ value: {} }, ["value"]),
    doc: "True when the input equals `value` exactly (for ticking a checkbox on a matching option).",
  },
  {
    name: "contains",
    fn: (item, { value }) => {
      if (item === null) return false;
      if (typeof item === "string") return typeof value === "string" && item.includes(value);
      if (Array.isArray(item)) return item.some((each) => pyEquals(each, value));
      if (isDict(item)) {
        if (Array.isArray(value) || isDict(value)) throw new PyError(`unhashable type: '${pyTypeName(value)}'`);
        return typeof value === "string" && hasKey(item, value);
      }
      throw new TransformError(`contains expects a list or text but got ${pyTypeName(item)}: ${pyRepr(item)}`);
    },
    schema: obj({ value: {} }, ["value"]),
    doc: "True when `value` is an item of the input list or a substring of the input text.",
  },
  {
    name: "default",
    fn: (item, { value }) => (item === null || item === "" ? value : item),
    schema: obj({ value: {} }, ["value"]),
    doc: "Use `value` when the input is missing or an empty string.",
  },
  {
    name: "prefix",
    fn: (item, { value }) => decorate(item, value, true),
    schema: obj({ value: STR }, ["value"]),
    doc: "Put fixed text before the input (blank input stays blank).",
  },
  {
    name: "suffix",
    fn: (item, { value }) => decorate(item, value, false),
    schema: obj({ value: STR }, ["value"]),
    doc: "Put fixed text after the input (blank input stays blank).",
  },
];

/** name -> {fn(value, args), schema, doc, takesList}, in Python's registration order. */
const REGISTRY = new Map(BUILTINS.map((t) => [t.name, { takesList: false, ...t }]));

/**
 * Registered transforms, in registration order, as `{name, args, takesList, doc}`.
 * `args` is the JSON Schema for a step's args. Python's `list_transforms()` lists the same names,
 * schemas and docs.
 * @returns {{name: string, args: object, takesList: boolean, doc: string}[]}
 */
export function listTransforms() {
  return [...REGISTRY].map(([name, e]) => ({
    name,
    args: structuredClone(e.schema),
    takesList: e.takesList,
    doc: e.doc,
  }));
}

/**
 * Check a chain without running it.
 * @param {{op: string, args?: object}[]} chain
 * @returns {string[]} error messages in Python's words (empty when the chain is valid)
 */
export function validateChain(chain) {
  const errors = [];
  for (const step of chain) {
    const entry = REGISTRY.get(step.op);
    if (entry === undefined) {
      errors.push(`unknown transform ${pyRepr(step.op)}`);
      continue;
    }
    const found = schemaErrors(entry.schema, step.args ?? {}, []).sort((a, b) => comparePaths(a.path, b.path));
    for (const err of found) {
      const where = err.path.map((p) => `[${pyRepr(p)}]`).join("");
      errors.push(`bad args for transform ${pyRepr(step.op)}${where ? ` at args${where}` : ""}: ${err.message}`);
    }
  }
  return errors;
}

function call(step, entry, value) {
  try {
    return entry.fn(value, step.args ?? {});
  } catch (e) {
    if (e instanceof TransformError) throw e;
    // a transform misbehaving must not escape as a bare error
    throw new TransformError(`transform ${pyRepr(step.op)} failed on ${pyRepr(value)}: ${e.message}`);
  }
}

/**
 * Run `chain` over the source `values` and return the result.
 * Throws TransformError if the chain is invalid or a transform rejects a value. Returns null when
 * there are no source values at all; a single resulting value is returned bare, several as a list.
 * @param {unknown[]} values
 * @param {{op: string, args?: object}[]} chain
 * @returns {any}
 */
export function applyChain(values, chain) {
  const errors = validateChain(chain);
  if (errors.length) throw new TransformError(errors.join("; "));

  let current = [...values];
  let multi = true; // `current` is the list of source values (vs. one value)
  for (const step of chain) {
    const entry = REGISTRY.get(step.op);
    if (entry.takesList) {
      if (multi) {
        // a lone source value that is itself a list (a multi-select) is what gets joined
        const loneList = current.length === 1 && Array.isArray(current[0]);
        current = call(step, entry, loneList ? current[0] : current);
      } else {
        current = call(step, entry, Array.isArray(current) ? current : [current]);
      }
      multi = false;
    } else if (multi && current.length === 1) {
      current = call(step, entry, current[0]);
      multi = false;
    } else if (multi) {
      current = current.map((v) => call(step, entry, v));
    } else {
      current = call(step, entry, current);
    }
  }

  if (multi) {
    if (!current.length) return null;
    return current.length === 1 ? current[0] : current;
  }
  return current;
}
